style.css:
@-moz-document domain("youtube.com") {
.ytp-play-progress {
        background: #ff0000 !important;
        box-shadow: 0 0 8px #ff0000 !important;
    }

    .ytp-scrubber-button {
        width: 24px !important;
        height: 24px !important;
        border-radius: 50% !important;
        background:
            radial-gradient(circle at 30% 30%, #700000 0 2px, transparent 3px),
            radial-gradient(circle at 65% 25%, #990000 0 3px, transparent 4px),
            radial-gradient(circle at 45% 55%, #720000 0 3px, transparent 4px),
            radial-gradient(circle at 75% 65%, #a00000 0 2px, transparent 3px),
            radial-gradient(circle at 25% 75%, #680000 0 2px, transparent 3px),
            radial-gradient(circle, #ff3333 0%, #d40000 55%, #650000 100%) !important;
        border: 2px solid #ff4444 !important;
        box-shadow: 0 0 8px #ff0000, 0 0 18px #ff0000 !important;
    }
}
